class Solution {
  public long minimumMoves(int[] nums, int k, int maxChanges) {
    int n = nums.length;
    // longest run of ones around one index, capped at 3 (the index and its two neighbours)
    int adjacent = 0, run = 0;
    for (int x : nums) {
      run = x == 1 ? run + 1 : 0;
      adjacent = Math.max(adjacent, Math.min(run, 3));
    }
    if (k <= adjacent + maxChanges) {
      int free = Math.min(k, adjacent);
      return (free > 0 ? free - 1 : 0) + 2L * (k - free);
    }
    int need = k - maxChanges; // ones that must be walked to
    int[] pos = new int[n];
    int ones = 0;
    for (int i = 0; i < n; i++) if (nums[i] == 1) pos[ones++] = i;
    long[] prefix = new long[ones + 1];
    for (int i = 0; i < ones; i++) prefix[i + 1] = prefix[i] + pos[i];
    long best = Long.MAX_VALUE;
    for (int l = 0; l + need <= ones; l++) {
      int r = l + need, mid = l + need / 2;
      long cost =
          (long) pos[mid] * (mid - l)
              - (prefix[mid] - prefix[l])
              + (prefix[r] - prefix[mid + 1])
              - (long) pos[mid] * (r - mid - 1);
      best = Math.min(best, cost);
    }
    return best + 2L * maxChanges;
  }
}
